package main

import (
	_ "embed"
	"encoding/json"

	"github.com/Silo-Server/silo-plugin-sdk/pkg/pluginsdk/runtime"

	"github.com/Moonfin-Client/Plugin/Silo/internal/api"
	"github.com/Moonfin-Client/Plugin/Silo/internal/store"
)

// version is set at build time with -ldflags "-X main.version=...".
var version string

//go:embed manifest.json
var manifestJSON []byte

// configSchema is Silo's settings form, generated by tools/genform.
//
//go:embed config_schema.json
var configSchema []byte

func main() {
	server := api.NewServer(version, store.HostKV{}, api.NewHostCatalog())
	runtime.ServeManifestWithOptions(withConfigSchema(manifestJSON, configSchema), version,
		runtime.CapabilityServers{HttpRoutes: server}, runtime.WithConfigure(server.Configure))
}

func withConfigSchema(manifest, schema []byte) []byte {
	var m map[string]json.RawMessage
	if err := json.Unmarshal(manifest, &m); err != nil {
		panic(err)
	}
	m["global_config_schema"] = schema
	out, err := json.Marshal(m)
	if err != nil {
		panic(err)
	}
	return out
}
